#include "../src/world_material.h"
#include <stdio.h>
int main(void){unsigned count,a[4];while(scanf("%u %u %u %u %u",&count,a,a+1,a+2,a+3)==5){unsigned char poly[24]={0},m[28]={0};m[16]=255;for(unsigned i=0;i<4;i++){poly[16+2*i]=(unsigned char)a[i];poly[17+2*i]=(unsigned char)(a[i]>>8);}TaxiWorldAsset w={.np=1,.nm=1,.polygons=poly,.materials=m};TaxiWorldRenderPolygon g={.count=count};for(unsigned i=0;i<4;i++)g.vertices[i]=(TaxiPoint){(int)i+1,(int)i+11,(int)i+21};TaxiWorldMaterialPolygon out;if(taxi_world_material_polygon(&w,0,&g,0,256,&out))return 2;if(out.count!=count)return 3;for(unsigned i=0;i<count;i++)if(out.vertices[i].x!=(int)i+1||out.vertices[i].y!=(int)i+11||out.vertices[i].z!=(int)i+21)return 4;printf("%u ",out.texture);for(unsigned i=0;i<4;i++)printf("%ld ",(long)out.vertices[i].attribute);puts("");}return 0;}
